import type { Subscription, WorkspaceLockReason } from "@/types/billing";
import type { OrgId } from "@/types/common";

/**
 * Billing lock rules.
 *
 * A workspace whose subscription is not in good standing is read-only. This
 * module owns the pure rule — which subscription states lock, and from when —
 * so the service guard, the billing summary and the shell banner can never
 * disagree about whether an org is locked.
 */

/** Raised by `assertWorkspaceWritable()` when a member write hits a locked org. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded" as const;

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`This workspace is read-only until billing is resolved (${reason}).`);
    this.name = "WorkspaceLockedError";
  }
}

/**
 * Why the workspace is locked at `now`, or `null` when it is writable.
 *
 * No subscription row and `active` are writable. `past_due` locks outright;
 * a trial locks once its period end is reached; a cancellation locks once its
 * date is reached, and a cancellation with no date counts as effective now.
 */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (subscription === null) return null;

  switch (subscription.status) {
    case "active":
      return null;
    case "past_due":
      return "past_due";
    case "trialing":
      return hasReached(now, subscription.currentPeriodEnd)
        ? "trial_ended"
        : null;
    case "canceled":
      return subscription.cancelAt === null ||
        hasReached(now, subscription.cancelAt)
        ? "canceled"
        : null;
  }
}

function hasReached(now: Date, moment: string): boolean {
  return now.getTime() >= new Date(moment).getTime();
}

