/**
 * Inline banner for page-level messages.
 *
 * Owner A — design system. Server-renderable: `error.tsx` boundaries and plan
 * limit warnings both render through it. Danger and warning tones announce
 * themselves assertively; the quieter tones do not steal focus.
 */
import type { ReactElement, ReactNode } from "react";
import { cn } from "@/lib/cn";
import { TONE_SURFACE } from "./_lib/tokens";

export type AlertProps = { tone?: 'info' | 'success' | 'warning' | 'danger'; title: string; className?: string; children?: ReactNode };

const ICONS = {
  info: "i",
  success: "✓",
  warning: "!",
  danger: "!",
} as const;

export function Alert(props: AlertProps): ReactElement | null {
  const { tone = "info", title, className, children } = props;

  const assertive = tone === "danger" || tone === "warning";

  return (
    <div
      role={assertive ? "alert" : "status"}
      aria-live={assertive ? "assertive" : "polite"}
      className={cn(
        "flex gap-3 rounded-md border px-3 py-2.5 text-sm",
        TONE_SURFACE[tone],
        className,
      )}
    >
      <span
        aria-hidden="true"
        className="mt-0.5 inline-flex h-4 w-4 shrink-0 items-center justify-center rounded-full border border-current text-[10px] font-bold"
      >
        {ICONS[tone]}
      </span>
      <div className="min-w-0">
        <p className="font-medium">{title}</p>
        {children !== undefined ? (
          <div className="mt-0.5 text-[13px] opacity-90">{children}</div>
        ) : null}
      </div>
    </div>
  );
}
/**
 * Upgrade prompt shown when seats are exhausted.
 *
 * Must call (do not reimplement): can
 */
import Link from "next/link";
import { Alert } from "@/components/ui/alert";
import { formatCount, formatLimit } from "@/lib/format";
import { can } from "@/lib/permissions";
import { settingsPath } from "@/lib/url";
import type { LimitCheck } from "@/types/billing";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { billingResource } from "../permission/resources";

export type SeatLimitBannerProps = {
  check: LimitCheck;
  orgSlug: string;
  actor: Actor;
};

export function SeatLimitBanner(
  props: SeatLimitBannerProps,
): ReactElement | null {
  const { check, orgSlug, actor } = props;

  // Nothing to say until the org is actually at the wall.
  if (check.resource !== "seats" || !check.exceeded) return null;

  // Only the actor who could actually pay is offered the upgrade link.
  const mayUpgrade = can(actor, "org:manage_billing", billingResource(actor.orgId));

  return (
    <Alert tone="warning" title="All seats are in use">
      The {check.plan} plan includes {formatLimit(check.limit)} seats and{" "}
      {formatCount(check.used)} are taken, so new invitations will be refused.
      {mayUpgrade ? (
        <>
          {" "}
          <Link
            href={settingsPath(orgSlug, "billing")}
            className="font-medium underline"
          >
            Upgrade the plan
          </Link>{" "}
          to add more.
        </>
      ) : (
        " Ask an owner to upgrade the plan."
      )}
    </Alert>
  );
}

