import Link from "next/link";
import { Alert } from "@/components/ui/alert";
import { can } from "@/lib/permissions";
import { settingsPath } from "@/lib/url";
import type { WorkspaceLockReason } from "@/types/billing";
import type { Actor } from "@/types/member";
import type { ReactElement } from "react";
import { billingResource } from "../permission/resources";

export type WorkspaceLockBannerProps = {
  lockReason: WorkspaceLockReason | null;
  orgSlug: string;
  actor: Actor;
};

const TITLES: Readonly<Record<WorkspaceLockReason, string>> = {
  past_due: "Payment is past due",
  canceled: "The subscription has been canceled",
  trial_ended: "The trial has ended",
};

export function WorkspaceLockBanner(
  props: WorkspaceLockBannerProps,
): ReactElement | null {
  const { lockReason, orgSlug, actor } = props;

  if (lockReason === null) return null;

  // Billing is the way out of the lock, so only someone who can pay gets the link.
  const mayFix = can(actor, "org:manage_billing", billingResource(actor.orgId));

  return (
    <Alert tone="danger" title={TITLES[lockReason]}>
      This workspace is read-only: everything can still be viewed, but changes
      are refused.
      {mayFix ? (
        <>
          {" "}
          <Link
            href={settingsPath(orgSlug, "billing")}
            className="font-medium underline"
          >
            Update billing
          </Link>{" "}
          to unlock it.
        </>
      ) : (
        " Ask an owner to update billing."
      )}
    </Alert>
  );
}

