/**
 * The billing lock: a workspace whose subscription is not in good standing is
 * read-only for members, while reads, billing and Taskflow's own jobs go on.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
vi.mock("@/lib/rate-limit", async () => (await import("../server/_support/doubles/misc")).rateLimitModule);

import { lockReasonFor, WorkspaceLockedError } from "@/lib/billing-lock";
import { isDomainError, toAppError } from "@/lib/errors";
import { subscribe } from "@/lib/event-bus";
import { hashToken } from "@/lib/hash";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { getDb, subscriptions } from "@/server/db";
import { runTrialExpiryJob } from "@/server/jobs/trial-expiry-job";
import { orgPredicate } from "@/server/repositories/base-repository";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as billingService from "@/server/services/billing-service";
import * as commentService from "@/server/services/comment-service";
import * as invitationService from "@/server/services/invitation-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as organizationService from "@/server/services/organization-service";
import * as projectService from "@/server/services/project-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import { toIsoTimestamp } from "@/types/common";
import type { Subscription, SubscriptionStatus } from "@/types/billing";
import type { IsoTimestamp, OrgId } from "@/types/common";

const MS_PER_DAY = 24 * 60 * 60 * 1000;

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

/** Rewrites the stored subscription, the way the billing provider would. */
function setSubscription(
  orgId: OrgId,
  patch: Partial<{
    status: SubscriptionStatus;
    currentPeriodEnd: IsoTimestamp;
    cancelAt: IsoTimestamp | null;
  }>,
): void {
  getDb()
    .update(subscriptions)
    .set(patch)
    .where(orgPredicate(subscriptions.orgId, orgId))
    .run();
}

function subscription(overrides: Partial<Subscription>): Subscription {
  return {
    id: "01SUB" as Subscription["id"],
    orgId: "01ORG" as OrgId,
    plan: "growth",
    interval: "monthly",
    status: "active",
    seats: 1,
    currentPeriodStart: "2026-01-01T00:00:00.000Z" as IsoTimestamp,
    currentPeriodEnd: "2026-02-01T00:00:00.000Z" as IsoTimestamp,
    cancelAt: null,
    createdAt: "2026-01-01T00:00:00.000Z" as IsoTimestamp,
    updatedAt: "2026-01-01T00:00:00.000Z" as IsoTimestamp,
    ...overrides,
  };
}

describe("lockReasonFor", () => {
  const before = new Date("2026-01-31T23:59:59.999Z");
  const at = new Date("2026-02-01T00:00:00.000Z");

  it("leaves a workspace without a subscription, or an active one, writable", () => {
    expect(lockReasonFor(null, at)).toBeNull();
    expect(lockReasonFor(subscription({ status: "active" }), at)).toBeNull();
  });

  it("locks a past-due subscription", () => {
    expect(lockReasonFor(subscription({ status: "past_due" }), before)).toBe("past_due");
  });

  it("locks a trial from the moment its period ends", () => {
    const trial = subscription({ status: "trialing" });
    expect(lockReasonFor(trial, before)).toBeNull();
    expect(lockReasonFor(trial, at)).toBe("trial_ended");
  });

  it("locks a cancellation once its date is reached, or at once without one", () => {
    const scheduled = subscription({
      status: "canceled",
      cancelAt: "2026-02-01T00:00:00.000Z" as IsoTimestamp,
    });
    expect(lockReasonFor(scheduled, before)).toBeNull();
    expect(lockReasonFor(scheduled, at)).toBe("canceled");
    expect(lockReasonFor(subscription({ status: "canceled", cancelAt: null }), before)).toBe(
      "canceled",
    );
  });
});

describe("the error mapping", () => {
  it("maps WorkspaceLockedError to plan_limit_exceeded with the reason", () => {
    const error = new WorkspaceLockedError("01ORG" as OrgId, "past_due");
    expect(error.code).toBe("plan_limit_exceeded");
    expect(isDomainError(error)).toBe(true);

    const shape = toAppError(error);
    expect(shape.code).toBe("plan_limit_exceeded");
    expect(shape.meta?.reason).toBe("past_due");
  });
});

describe("a locked workspace", () => {
  it("refuses member writes without writing or publishing anything", async () => {
    const tenant = await createTenant("lock-writes");
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id),
    );
    setSubscription(tenant.org.id, { status: "past_due" });

    const published: unknown[] = [];
    const off = subscribe("issue.created", (payload) => {
      published.push(payload);
    });

    try {
      await expect(
        issueService.createIssue(
          tenant.actors.member,
          issueInput(tenant.org.id, tenant.project.id, { title: "Refused" }),
        ),
      ).rejects.toBeInstanceOf(WorkspaceLockedError);

      await expect(
        issueService.moveIssue(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          toStatus: "in_progress",
          toIndex: 0,
        } as never),
      ).rejects.toMatchObject({ reason: "past_due", orgId: tenant.org.id });

      await expect(
        commentService.createComment(tenant.actors.member, {
          orgId: tenant.org.id,
          issueId: issue.id,
          body: "Refused",
          parentId: null,
          mentionedUserIds: [],
        }),
      ).rejects.toBeInstanceOf(WorkspaceLockedError);

      await expect(
        projectService.archiveProject(tenant.actors.owner, {
          orgId: tenant.org.id,
          projectId: tenant.project.id,
          archiveIssues: true,
        }),
      ).rejects.toBeInstanceOf(WorkspaceLockedError);
    } finally {
      off();
    }

    expect(published).toHaveLength(0);
    await expect(issueRepo.countIssues(tenant.org.id, tenant.project.id)).resolves.toBe(1);
    await expect(
      issueRepo.findIssueById(tenant.org.id, issue.id),
    ).resolves.toMatchObject({ status: issue.status, archivedAt: null });
  });

  it("still gives a caller who would have been refused anyway the same refusal", async () => {
    const tenant = await createTenant("lock-precedence");
    const other = await createTenant("lock-precedence-other");
    setSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      projectService.createProject(tenant.actors.viewer, {
        orgId: tenant.org.id,
        name: "Nope",
      } as never),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      issueService.createIssue(
        other.actors.owner,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("keeps reads, billing, notification housekeeping and deletion working", async () => {
    const tenant = await createTenant("lock-allowed");
    setSubscription(tenant.org.id, { status: "canceled", cancelAt: null });

    await expect(
      issueService.listIssues(tenant.actors.member, {
        orgId: tenant.org.id,
        limit: 10,
        cursor: null,
      } as never),
    ).resolves.toBeDefined();

    await expect(
      billingService.getBillingSummary(tenant.actors.owner, tenant.org.id),
    ).resolves.toMatchObject({ lockReason: "canceled" });
    await expect(
      organizationService.getOrganizationSummary(tenant.actors.member, tenant.org.id),
    ).resolves.toMatchObject({ lockReason: "canceled" });

    await expect(
      notificationService.markAllRead(tenant.actors.member, tenant.org.id),
    ).resolves.toBe(0);

    await expect(
      billingService.updateSeats(tenant.actors.owner, { orgId: tenant.org.id, seats: 2 }),
    ).resolves.toMatchObject({ seats: 2 });

    await expect(
      organizationService.deleteOrganization(tenant.actors.owner, {
        orgId: tenant.org.id,
        confirmSlug: tenant.org.slug,
      }),
    ).resolves.toMatchObject({ id: tenant.org.id });
  });

  it("becomes writable again after a successful plan change", async () => {
    const tenant = await createTenant("lock-plan-change");
    setSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id),
    ).rejects.toBeInstanceOf(WorkspaceLockedError);

    await billingService.changePlan(tenant.actors.owner, {
      orgId: tenant.org.id,
      plan: "enterprise",
      interval: "monthly",
    });

    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
    await expect(
      issueService.createIssue(
        tenant.actors.member,
        issueInput(tenant.org.id, tenant.project.id),
      ),
    ).resolves.toMatchObject({ orgId: tenant.org.id });
  });

  it("stays writable until a scheduled cancellation takes effect", async () => {
    const tenant = await createTenant("lock-scheduled-cancel");
