    await expect(billingService.assertWorkspaceWritable(tenant.org.id)).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(tenant.org.id, new Date(cancelAt)),
    ).rejects.toMatchObject({ reason: "canceled" });
  });

  it("leaves an invitation into a locked workspace pending", async () => {
    const tenant = await createTenant("lock-invite");
    const rawToken = "l".repeat(32);
    await invitationRepo.insertInvitation(
      tenant.org.id,
      {
        orgId: tenant.org.id,
        email: "joiner@lock-invite.test",
        role: "member",
        expiresInDays: 14,
      },
      tenant.userIds.admin,
      hashToken(rawToken),
    );
    const joiner = await userRepo.insertUser({
      email: "joiner@lock-invite.test",
      name: "Joiner",
      passwordHash: "seed",
    });
    setSubscription(tenant.org.id, { status: "past_due" });

    await expect(
      invitationService.acceptInvitation(joiner.id, { token: "z".repeat(32) }),
    ).rejects.not.toBeInstanceOf(WorkspaceLockedError);

    await expect(
      invitationService.acceptInvitation(joiner.id, { token: rawToken }),
    ).rejects.toBeInstanceOf(WorkspaceLockedError);

    await expect(memberRepo.findMember(tenant.org.id, joiner.id)).resolves.toBeNull();
    await expect(
      invitationRepo.findInvitationByTokenHash(hashToken(rawToken)),
    ).resolves.toMatchObject({ acceptedAt: null, revokedAt: null });
  });
});

describe("the trial-expiry job", () => {
  it("unlocks an ended trial that fits the free plan, and leaves an oversized one locked", async () => {
    const fits = await createTenant("lock-trial-fits");
    const oversized = await createTenant("lock-trial-oversized");
    await usageRepo.incrementUsage(oversized.org.id, { seatsUsed: 10 });

    const ended = new Date(Date.now() + 15 * MS_PER_DAY);
    await expect(
      billingService.assertWorkspaceWritable(fits.org.id, ended),
    ).rejects.toMatchObject({ reason: "trial_ended" });

    await runTrialExpiryJob(ended);

    await expect(
      billingService.assertWorkspaceWritable(fits.org.id, ended),
    ).resolves.toBeUndefined();
    await expect(
      billingService.assertWorkspaceWritable(oversized.org.id, ended),
    ).rejects.toMatchObject({ reason: "trial_ended" });
  });
});

